import base64,os
def u(n):
    p=f"img/{n}.jpg" if os.path.exists(f"img/{n}.jpg") else f"img/{n}.png"
    m="jpeg" if p.endswith("jpg") else "png"
    return f"data:image/{m};base64,"+base64.b64encode(open(p,"rb").read()).decode()
def im(n,alt="",cls=""): return f'<img class="{cls}" src="{u(n)}" alt="{alt}" loading="lazy">'
def hd(r): return f'<div class="hd"><span>BHARAT CONNECT · LONDON</span><span class="o">{r}</span></div>'
def ft(t,n): return f'<div class="ft"><i>{t}</i><b>{n}</b></div>'
FT1="Bharat Mahotsav London Feb - 2027"
def page(id,r,body,t="Bharat Mahotsav",n="",bridge=False):
    b='<div class="bridge"></div>' if bridge else ''
    return f'<section class="page" id="{id}">{hd(r)}{body}{b}{ft(t,n)}</section>'
def h(t,o="",tag="h2"): return f'<{tag} class="h">{t}{" <em>"+o+"</em>" if o else ""}</{tag}><i class="bar"></i>'
def ppl(items,cols):
    s=f'<div class="ppl c{cols}">'
    for f,n,r in items: s+=f'<figure>{im(f,n)}<figcaption><b>{n}</b><span>{r}</span></figcaption></figure>'
    return s+'</div>'
def lis(items): return '<ul class="sq">'+''.join(f'<li>{x}</li>' for x in items)+'</ul>'
P=[]
# cover
P.append(f'<section class="cover" id="top">{im("p01_00","Bharat Connect International Business Summit London 19–22 February 2027 — 50+ Startups","bg")}<div class="bc"></div></section>')
# 2 itinerary
P.append(page("itinerary","19–22 FEBRUARY 2027",f'''{h("Festival","Itinerary","h1")}
<div class="g2"><div class="day"><div class="d">19<sup>th</sup><b>FEB 2027</b></div><h3>Introductory Meet &amp; Greet</h3><p>Moderated meet-and-greet session with brief opening remarks, followed by structured speed-networking.</p>{lis(["Dinner"])}</div>
<div class="day"><div class="d">20<sup>th</sup><b>FEB 2027</b></div><h3>Orientation – Leadership &amp; Entrepreneurship at Prestigious University</h3><ul class="sq two"><li>Campus Tour</li><li>Lunch</li><li>Welcome Note</li><li>Keynote Sessions</li><li>Panel Discussion</li><li>Orientation &amp; Lecture</li><li>Felicitations</li></ul></div>
<div class="day nv"><div class="d">21<sup>st</sup><b>FEB 2027</b></div><h3>Bharat Connect – Business Summit</h3>{lis(["Registration &amp; Morning Coffee Networking","Opening Remarks &amp; Welcome Speech","Keynote Address","Panel Discussions","Tea/Coffee Break","Startup Pitch Showcase (Batch 1)","Lunch","Startup Pitch Showcase (Batch 2)","Hi-Tea &amp; Refreshment Break","Startup Pitch Showcase (Batch 3)","<strong>Airwalks – Fashion Show</strong>"])}</div>
<div class="day"><div class="d">22<sup>nd</sup><b>FEB 2027</b></div><h3>Silver Service Lunch at House of Lords</h3><p>Meet &amp; greet to bring together thought leaders, entrepreneurs, investors, artists, cultural icons and global stakeholders to showcase India’s diverse legacy.</p></div></div>''',FT1,"02",True))
# 3 about
P.append(page("about","ABOUT",f'''<div class="num">{h("<span class='o'>01</span> About Bharat Mahotsav")}</div>
<div class="g2 sp"><div><p>Conceived and founded by <b>Dr. Amitabh Shrivastav, Dr. Smita Shrivastav, &amp; Mr. Vijay Tiwari</b>, Bharat Mahotsav is a global platform dedicated to celebrating and promoting India’s business ecosystem, heritage, art, culture and fashion on the world stage.</p><p>The festival brings together thought leaders, entrepreneurs, investors, artists, cultural icons and global stakeholders to showcase India’s diverse legacy while creating opportunities for international collaboration and economic engagement.</p><blockquote>“Bharat Mahotsav is where tradition meets innovation, culture meets commerce, and India connects with the world. One India. One Vision. One Future.”</blockquote></div>
<div class="side"><small class="lab">CORE PLATFORMS</small>{lis(["<b>Bharat Connect</b> — Business Summit","<b>Startup Showcase</b> — Aligned with Startup India, DPIIT","<b>Airwalks</b> — Fashion &amp; Culture","<b>Bharat Gaurav Samman</b> — Felicitation"])}{im("p03_00","Bharat Mahotsav","lg1")}</div></div>
<hr class="hr"><div class="num">{h("<span class='o'>02</span> Bharat Connect — Startup Showcase &amp; Business Summit")}</div>
<div class="g2 sp"><div><p class="lead2">Bharat Connect is a premier business and investment platform focused on strengthening economic collaboration between India and the global business community.</p><p>To be held in London, the summit creates opportunities across:</p><p>It brings together industry leaders, entrepreneurs, investors, policymakers and global business partners — connecting Indian enterprises with global investors and markets.</p></div>
<div class="side">{im("bc","Bharat Connect","lg2")}<blockquote>Heritage Inspires Progress. Culture Connects People. Innovation Drives Tomorrow.</blockquote></div></div>
{im("p03_02","Past Bharat Mahotsav moments","strip")}''',FT1,"03"))
# 4 showcase
P.append(page("showcase","FEATURED PROGRAMME",f'''<div class="num">{h("<span class='o'>02.1</span> Startup Showcase — Featured Programme")}</div>
<div class="g2 sp"><p class="big">Where India's next big idea meets <span class="o">the world's stage.</span></p><div class="r">{im("p04_00","DPIIT Startup India","lg3")}</div></div>
<div class="g2"><div><p>A major highlight of the Bharat Connect’s Business Summit will be the Startup Showcase, aligned with the vision and objectives of the Government of India’s Startup India initiative, led by the Department for Promotion of Industry and Internal Trade.</p><p>Startup India, DPIIT seeks to transform India into a nation of job creators, building a strong and inclusive ecosystem that encourages innovation, drives sustainable economic growth, and enables Indian startups and technologies to scale globally.</p></div><div><p>Through the Startup Showcase, Bharat Connect 2027 will provide a platform for selected Indian startups to present their innovations, products, technologies, and business models to an international audience comprising investors, industry leaders, business partners, media, and potential customers from the UK and world wide.</p><p>The initiative will help create meaningful India–UK connections, opening pathways for investment, collaboration, market access, and global expansion.</p></div></div>
<div class="nvb"><h3 class="h">Day Structure</h3><i class="bar"></i>{lis(["<b>Panel Discussion</b> — Key Imperatives for Building, Sustaining High-Growth Ventures and Market Expansion.","<b>Showcase Sessions</b> — 50+ startups presenting alongside mentors, incubators and investors, with structured sessions for pitching, mentorship and deal-making.","<b>Certificate Ceremony</b> — The day concludes with certificates presented to all participating startups and delegates, recognising their participation on this global platform."])}</div>
{im("p04_01","Startup Showcase moments","strip")}''',FT1,"04"))
